import warnings
from scipy.optimize._linesearch import scalar_search_wolfe2

def phi(alpha):
    """phi(alpha) = (alpha - 5)^2"""
    return (alpha - 5) ** 2

def derphi(alpha):
    """derphi(alpha) = 2 * (alpha - 5)"""
    return 2 * (alpha - 5)

# Capture warnings
warning_count = 0
warning_msg = None

with warnings.catch_warnings(record=True) as w:
    warnings.simplefilter('always')
    result = scalar_search_wolfe2(phi, derphi, amax=0.001)
    if len(w) > 0:
        warning_count = 1
        warning_msg = str(w[0].message)

alpha_star, phi_star, derphi_star, extra = result

# Record observations
probe('warning_raised', float(warning_count))
if alpha_star is not None:
    probe('alpha_star', alpha_star)
else:
    probe('alpha_star', float('nan'))
if phi_star is not None:
    probe('phi_star', phi_star)
else:
    probe('phi_star', float('nan'))
if derphi_star is not None:
    probe('derphi_star', derphi_star)
else:
    probe('derphi_star', float('nan'))

